	array( 'title' => 'House of Waterford Crystal', 'slug' => 'house-of-waterford-crystal', 'county' => 'Waterford', 'town' => 'Waterford', 'category' => 'Cultura', 'official_website' => 'https://www.waterfordvisitorcentre.com/', 'discover_ireland' => '', 'excerpt' => 'Fábrica e centro de visitantes do cristal Waterford, com tour pela produção e galeria de peças únicas.', 'content' => '<p>O tour pela House of Waterford Crystal mostra artesãos soprando, cortando e gravando o cristal mais famoso da Irlanda. A galeria exibe troféus esportivos e peças monumentais.</p>', 'indoor' => true, 'booking' => true ),
	array( 'title' => 'Waterford Treasures Museums', 'slug' => 'waterford-treasures', 'county' => 'Waterford', 'town' => 'Waterford', 'category' => 'Museus', 'official_website' => 'https://www.waterfordtreasures.com/', 'discover_ireland' => '', 'excerpt' => 'Conjunto de museus sobre a Irlanda viking e medieval, no coração do Viking Triangle.', 'content' => '<p>Os Waterford Treasures reúnem três museus — Viking, Medieval e Bishop\'s Palace — que contam 1.100 anos de história da cidade mais antiga da Irlanda, fundada pelos vikings em 914.</p>', 'indoor' => true ),
	array( 'title' => "Reginald's Tower", 'slug' => 'reginals-tower', 'county' => 'Waterford', 'town' => 'Waterford', 'category' => 'História', 'official_website' => 'https://heritageireland.ie/places-to-visit/reginalds-tower/', 'discover_ireland' => '', 'excerpt' => 'Torre viking do século XIII, o edifício civil mais antigo da Irlanda em uso contínuo.', 'content' => '<p>Reginald\'s Tower guarda memórias dos vikings, do casamento de Strongbow e Aoife e da chegada de Strongbow. Hoje é museu do Waterford Treasures, com a espada viking de Waterford em exposição.</p>', 'indoor' => true ),
	array( 'title' => 'Waterford Greenway', 'slug' => 'waterford-greenway', 'county' => 'Waterford', 'town' => 'Waterford – Dungarvan', 'category' => 'Greenways', 'official_website' => 'https://deisegreenway.com/', 'discover_ireland' => 'https://www.discoverireland.ie/waterford/waterford-greenway', 'excerpt' => 'Greenway de 46 km sobre antiga ferrovia, com viadutos, túnel e travessia do rio Suir — a mais popular da Irlanda.', 'content' => '<p>O Waterford Greenway (Deise Greenway) liga a cidade a Dungarvan por 46 km planos, cruzando o rio Suir em ponte de 200 m, passando por 11 pontes e um túnel de 400 m. Aluguel de bicicletas nas duas pontas.</p>', 'outdoor' => true, 'family' => true, 'free' => true ),
	array( 'title' => 'Copper Coast Geopark', 'slug' => 'copper-coast-geopark', 'county' => 'Waterford', 'town' => 'Bunmahon', 'category' => 'Natureza', 'official_website' => 'https://coppercoastgeopark.com/', 'discover_ireland' => '', 'excerpt' => 'Litoral de 25 km com falésias, praias e geologia vulcânica de 460 milhões de anos, patrimônio UNESCO.', 'content' => '<p>A Copper Coast combina praias como Bunmahon e Annestown com penhascos de rocha vulcânica antiga. O centro geológico em Bunmahon explica a história de 460 milhões de anos da costa.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Mount Congreve Gardens', 'slug' => 'mount-congreve-gardens', 'county' => 'Waterford', 'town' => 'Kilmeaden', 'category' => 'Jardins', 'official_website' => 'https://mountcongreve.com/', 'discover_ireland' => 'https://www.discoverireland.ie/waterford/mount-congreve-gardens', 'excerpt' => 'Um dos maiores jardins privados da Europa, com 70 acres de azaleias, rododendros e bosques plantados por Ambrose Congreve.', 'content' => '<p>Mount Congreve é famoso pela coleção de azaleias e rododendros que explode em cores na primavera. Ambrose Congreve dedicou 80 anos ao jardim, hoje aberto ao público com café e viveiro.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Lismore Castle Gardens', 'slug' => 'lismore-castle-gardens', 'county' => 'Waterford', 'town' => 'Lismore', 'category' => 'Jardins', 'official_website' => 'https://lismorecastle.com/', 'discover_ireland' => 'https://www.discoverireland.ie/waterford/lismore-castle-gardens', 'excerpt' => 'Jardins históricos do castelo dos duques de Devonshire, com upper e lower gardens sobre o rio Blackwater.', 'content' => '<p>O castelo de Lismore, residência irlandesa dos Devonshires, não é aberto, mas seus jardins em dois níveis sim. Destaques: o jardim murado do século XVII e a vista do vale do Blackwater.</p>', 'outdoor' => true ),
	array( 'title' => 'Ardmore Round Tower & Cathedral', 'slug' => 'ardmore-round-tower', 'county' => 'Waterford', 'town' => 'Ardmore', 'category' => 'História', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/waterford/ardmore-round-tower-and-cathedral', 'excerpt' => 'Sítio monástico de São Declan com torre redonda de 30 m, catedral com esculturas e oratório primitivo.', 'content' => '<p>Ardmore é um dos sítios cristãos mais antigos da Irlanda, fundado por São Declan antes da chegada de Patrício. A torre redonda, a catedral com frisos esculpidos e o oratório de pedra formam um conjunto raro.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Coumshingaun Loop (Comeragh Mountains)', 'slug' => 'coumshingaun-loop', 'county' => 'Waterford', 'town' => 'Kilclooney', 'category' => 'Caminhadas', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Trilha circular em torno de um lago glaciar num circo de falésias — uma das caminhadas mais espetaculares do sul.', 'content' => '<p>O Coumshingaun Loop contorna o lago glaciar de Coumshingaun, cercado por paredes de 300 metros nas Comeragh Mountains. A trilha de 7,5 km exige bom preparo físico, mas é acessível sem equipamento.</p>', 'outdoor' => true, 'free' => true ),

	// ---- WEXFORD (+9) ----
	array( 'title' => 'Irish National Heritage Park', 'slug' => 'irish-national-heritage-park', 'county' => 'Wexford', 'town' => 'Ferrycarrig', 'category' => 'História', 'official_website' => 'https://irishheritage.ie/', 'discover_ireland' => 'https://www.discoverireland.ie/wexford/irish-national-heritage-park', 'excerpt' => 'Parque de 35 acres que recria 9.000 anos de história irlandesa: cabanas do mesolítico, crannóg, mosteiro e anel normando.', 'content' => '<p>No Irish National Heritage Park, 16 sítios reconstituídos mostram como os irlandeses viveram do mesolítico à chegada dos normandos. Tours guiados, trilhas e até pernoite em cabana de caçador.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Johnstown Castle', 'slug' => 'johnstown-castle', 'county' => 'Wexford', 'town' => 'Wexford', 'category' => 'Castelos', 'official_website' => 'https://johnstowncastle.ie/', 'discover_ireland' => '', 'excerpt' => 'Castelo neogótico do século XIX com lagos, jardins e o Museu da Agricultura Irlandesa.', 'content' => '<p>Johnstown Castle combina um castelo gótico vitoriano, 50 hectares de jardins com lagos e grutas, e o Irish Agricultural Museum. Um dos passeios familiares mais completos do sudeste.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Hook Lighthouse', 'slug' => 'hook-lighthouse', 'county' => 'Wexford', 'town' => 'Hook Peninsula', 'category' => 'Patrimônio', 'official_website' => 'https://hookheritage.ie/', 'discover_ireland' => '', 'excerpt' => 'Farol medieval em operação desde o século XIII — um dos mais antigos do mundo — com tours e café.', 'content' => '<p>O Hook Head Lighthouse foi construído por William Marshal por volta de 1210 e ainda guia navios. Tours guiados sobem os 115 degraus; a península ao redor é rota cênica premiada.</p>', 'indoor' => true, 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Dunbrody Famine Ship', 'slug' => 'dunbrody-famine-ship', 'county' => 'Wexford', 'town' => 'New Ross', 'category' => 'Museus', 'official_website' => 'https://www.dunbrody.com/', 'discover_ireland' => '', 'excerpt' => 'Réplica fiel de um navio de emigrantes da Grande Fome, com tour imersivo sobre a travessia do Atlântico.', 'content' => '<p>O Dunbrody, construído em 1845, transportou milhares de irlandeses para a América. A réplica em New Ross oferece tour com atores interpretando passageiros — experiência comovente para quem conhece histórias de emigração.</p>', 'indoor' => true ),
	array( 'title' => 'Saltee Islands', 'slug' => 'saltee-islands', 'county' => 'Wexford', 'town' => 'Kilmore Quay', 'category' => 'Ilhas', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/wexford/saltee-islands', 'excerpt' => 'Santuário de aves marinhas com uma das maiores colônias de gansos-patola da Irlanda, acessível por barco de Kilmore Quay.', 'content' => '<p>As Great Saltee Islands abrigam dezenas de milhares de aves marinhas na primavera: gansos-patola, papagaios-do-mar e gaivotas. Barcos de passageiros partem de Kilmore Quay na temporada.</p>', 'outdoor' => true ),
	array( 'title' => 'Curracloe Beach', 'slug' => 'curracloe-beach', 'county' => 'Wexford', 'town' => 'Curracloe', 'category' => 'Praias', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/wexford/curracloe-beach', 'excerpt' => 'Praia de 11 km de areia fina, cenário da abertura de "O Resgate do Soldado Ryan", com dunas e trilhas.', 'content' => '<p>Curracloe é uma das praias mais premiadas da Irlanda, com águas rasas seguras e o Raven Nature Reserve nas dunas ao sul. Foi locação da cena de desembarque de "Saving Private Ryan".</p>', 'outdoor' => true, 'family' => true, 'free' => true ),
	array( 'title' => 'Wexford Wildfowl Reserve', 'slug' => 'wexford-wildfowl-reserve', 'county' => 'Wexford', 'town' => 'Wexford', 'category' => 'Vida Selvagem', 'official_website' => 'https://www.npws.ie/protected-sites/nature-reserves/wexford-wildfowl-reserve', 'discover_ireland' => '', 'excerpt' => 'Reserva natural no North Slob, refúgio de inverno de um terço da população mundial de gansos-de-frente-branca da Groenlândia.', 'content' => '<p>Gerida pelo NPWS, a reserva recebe milhares de aves migratórias entre outubro e março. A torre de observação e o centro de visitantes são gratuitos e acessíveis.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Ferns Castle', 'slug' => 'ferns-castle', 'county' => 'Wexford', 'town' => 'Ferns', 'category' => 'Castelos', 'official_website' => 'https://heritageireland.ie/places-to-visit/ferns-castle/', 'discover_ireland' => 'https://www.discoverireland.ie/wexford/ferns-castle', 'excerpt' => 'Castelo normando do século XIII com capela em cruz e vitrais modernos, na antiga capital dos reis de Leinster.', 'content' => '<p>Ferns foi sede dos MacMurrough, reis de Leinster. O castelo de William Marshal tem uma capela única em planta de cruz, com vitrais contemporâneos. Entrada gratuita.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Tintern Abbey', 'slug' => 'tintern-abbey-wexford', 'county' => 'Wexford', 'town' => 'Saltmills', 'category' => 'História', 'official_website' => 'https://heritageireland.ie/places-to-visit/tintern-abbey/', 'discover_ireland' => '', 'excerpt' => 'Abadia cisterciense fundada em 1200 por William Marshal, com colunata vitoriana e vale arborizado.', 'content' => '<p>William Marshal fundou Tintern Abbey em agradecimento por sobreviver a um naufrágio na costa de Wexford. A abadia, restaurada ao longo dos séculos, fica num vale tranquilo com trilhas.</p>', 'outdoor' => true ),

	// ---- TIPPERARY (+8) ----
	array( 'title' => 'Rock of Cashel', 'slug' => 'rock-of-cashel', 'county' => 'Tipperary', 'town' => 'Cashel', 'category' => 'História', 'official_website' => 'https://heritageireland.ie/places-to-visit/rock-of-cashel/', 'discover_ireland' => 'https://www.discoverireland.ie/tipperary/rock-of-cashel', 'excerpt' => 'Conjunto medieval espetacular sobre afloramento de calcário: catedral gótica, capela românica e torre redonda.', 'content' => '<p>O Rock of Cashel foi sede dos reis de Munster por séculos — São Patrício teria convertido o rei Aenghus aqui. A Capela de Cormac (1127) é a joia românica da Irlanda; a catedral gótica e a torre redonda completam o conjunto.</p>', 'outdoor' => true ),
	array( 'title' => 'Cahir Castle', 'slug' => 'cahir-castle', 'county' => 'Tipperary', 'town' => 'Cahir', 'category' => 'Castelos', 'official_website' => 'https://heritageireland.ie/places-to-visit/cahir-castle/', 'discover_ireland' => 'https://www.discoverireland.ie/tipperary/cahir-castle', 'excerpt' => 'Um dos castelos mais bem preservados da Irlanda, do século XIII, numa ilha do rio Suir.', 'content' => '<p>Cahir Castle resistiu a cercos e manteve suas muralhas, torres e masmorra quase intactas. O filme "Braveheart" usou o castelo como locação. Tours guiados incluem a torre de menagem.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Swiss Cottage', 'slug' => 'swiss-cottage', 'county' => 'Tipperary', 'town' => 'Cahir', 'category' => 'História', 'official_website' => 'https://heritageireland.ie/places-to-visit/swiss-cottage/', 'discover_ireland' => 'https://www.discoverireland.ie/tipperary/swiss-cottage', 'excerpt' => 'Chalé ornamental de 1810, exemplo perfeito do estilo "picturesque", com interior restaurado e floresta.', 'content' => '<p>O Swiss Cottage foi desenhado por John Nash como casa de lazer dos Cahir. Os interiores com papel de parede original e a trilha pela floresta até o castelo fazem parte da visita.</p>', 'indoor' => true ),
	array( 'title' => 'Glen of Aherlow', 'slug' => 'glen-of-aherlow', 'county' => 'Tipperary', 'town' => 'Bansha', 'category' => 'Natureza', 'official_website' => 'https://aherlow.com/', 'discover_ireland' => 'https://www.discoverireland.ie/glen-of-aherlow', 'excerpt' => 'Vale cênico entre as Galtee Mountains, com trilhas, mirante do Christ the King e vilas charmosas.', 'content' => '<p>O Glen of Aherlow se estende por 25 km entre as Galtee Mountains, a mais alta cadeia do interior. Rotas de caminhada, o mirante da estátua Christ the King e a vila de Bansha compõem o passeio.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'The Vee & Bay Lough', 'slug' => 'the-vee-bay-lough', 'county' => 'Tipperary', 'town' => 'Clogheen', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Passo de montanha em forma de V com mirante sobre o vale do Suir e o lago glaciar Bay Lough.', 'content' => '<p>The Vee é o desfiladeiro entre as Knockmealdown Mountains, famoso pelo mirante da "Vee Rock" e pelo Bay Lough, lago glaciar cercado de lendas. Rota cênica clássica entre Clogheen e Lismore.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Ormond Castle', 'slug' => 'ormond-castle', 'county' => 'Tipperary', 'town' => 'Carrick-on-Suir', 'category' => 'Castelos', 'official_website' => 'https://heritageireland.ie/places-to-visit/ormond-castle/', 'discover_ireland' => 'https://www.discoverireland.ie/tipperary/ormond-castle', 'excerpt' => 'Casa isabelina única na Irlanda, construída por Tomás Butler, 10º Conde de Ormond, junto a torres medievais.', 'content' => '<p>Ormond Castle combina duas torres medievais do século XV com uma mansão elisabetana de 1565 — a única do gênero na Irlanda. Os interiores com estuque e a lenda do amor por Elizabeth I atraem visitantes.</p>', 'indoor' => true ),
	array( 'title' => 'Mitchelstown Cave', 'slug' => 'mitchelstown-cave', 'county' => 'Tipperary', 'town' => 'Burncourt', 'category' => 'Natureza', 'official_website' => 'https://www.mitchelstowncave.com/', 'discover_ireland' => 'https://www.discoverireland.ie/tipperary/mitchelstown-cave', 'excerpt' => 'Uma das maiores cavernas da Europa, com estalactites gigantes, salões enormes e acústica de concertos.', 'content' => '<p>Mitchelstown Cave abriga o Tower of Babel, uma estalactite de 9 metros, e salões onde já se gravaram concertos por causa da acústica. Tours guiados percorrem 3 km de galerias iluminadas.</p>', 'indoor' => true, 'family' => true ),
	array( 'title' => 'Holy Cross Abbey', 'slug' => 'holy-cross-abbey', 'county' => 'Tipperary', 'town' => 'Holycross', 'category' => 'História', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Abadia cisterciense restaurada do século XII, famosa pela relíquia da Vera Cruz e ainda local de culto.', 'content' => '<p>Holy Cross Abbey recebeu seu nome da relíquia da Santa Cruz trazida no século XIII. Restaurada em 1975, é uma das poucas abadias medievais da Irlanda novamente usadas para missas.</p>', 'indoor' => true, 'free' => true ),

	// ---- LIMERICK (+7) ----
	array( 'title' => "King John's Castle", 'slug' => 'king-johns-castle-limerick', 'county' => 'Limerick', 'town' => 'Limerick', 'category' => 'Castelos', 'official_website' => 'https://kingjohnscastle.com/', 'discover_ireland' => '', 'excerpt' => 'Castelo normando de 1210 às margens do Shannon, com exposições interativas sobre cercos e história medieval.', 'content' => '<p>King John\'s Castle é um dos castelos normandos mais bem preservados da Europa. O centro de visitantes recria o cerco de 1642 e a vida medieval, com vista das muralhas para o rio Shannon.</p>', 'indoor' => true, 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Hunt Museum', 'slug' => 'hunt-museum', 'county' => 'Limerick', 'town' => 'Limerick', 'category' => 'Museus', 'official_website' => 'https://www.huntmuseum.com/', 'discover_ireland' => '', 'excerpt' => 'Coleção de arte e antiguidades dos Hunt, com Picasso, Renoir, Leonardo da Vinci e artefatos célticos.', 'content' => '<p>O Hunt Museum, no Custom House do século XVIII, exibe mais de 2.000 peças reunidas pela família Hunt: desde artefatos irlandeses antigos até desenhos atribuídos a Da Vinci e Picasso.</p>', 'indoor' => true ),
	array( 'title' => "St Mary's Cathedral", 'slug' => 'st-marys-cathedral-limerick', 'county' => 'Limerick', 'town' => 'Limerick', 'category' => 'História', 'official_website' => 'https://saintmaryscathedral.ie/', 'discover_ireland' => '', 'excerpt' => 'Catedral de 1168, o edifício em uso mais antigo de Limerick, com misericórdias medievais raras.', 'content' => '<p>Construída no local do palácio dos reis de Thomond, St Mary\'s Cathedral conserva misericórdias de coro do século XV e marcas de balas do cerco de 1691. Visitas guiadas revelam 850 anos de história.</p>', 'indoor' => true ),
	array( 'title' => 'Adare', 'slug' => 'adare-village', 'county' => 'Limerick', 'town' => 'Adare', 'category' => 'Cidades', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Vila considerada a mais bonita da Irlanda, com cottages de palha, mosteiros e o castelo dos Desmond.', 'content' => '<p>Adare combina cottages de telhado de palha, a abadia franciscana, o trinitarian abbey e o Desmond Castle em ruínas. Sede do Ryder Cup 2027, é parada obrigatória na rota Cork–Limerick.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Foynes Flying Boat & Maritime Museum', 'slug' => 'foynes-flying-boat-museum', 'county' => 'Limerick', 'town' => 'Foynes', 'category' => 'Museus', 'official_website' => 'https://www.flyingboatmuseum.com/', 'discover_ireland' => '', 'excerpt' => 'Museu na antiga base do Pan Am, com réplica em tamanho real do Boeing 314 e a origem do Irish Coffee.', 'content' => '<p>Foynes foi o hub do hidroavião transatlântico entre 1937 e 1945. O museu exibe uma réplica completa do Boeing 314 e conta a história do Irish Coffee, inventado aqui para aquecer passageiros.</p>', 'indoor' => true, 'family' => true ),
	array( 'title' => 'Lough Gur', 'slug' => 'lough-gur', 'county' => 'Limerick', 'town' => 'Bruff', 'category' => 'História', 'official_website' => 'https://loughgur.com/', 'discover_ireland' => 'https://www.discoverireland.ie/limerick/lough-gur', 'excerpt' => 'Lago em forma de rim cercado por megálitos, círculos de pedra e o Grange Stone Circle, o maior da Irlanda.', 'content' => '<p>Lough Gur é um dos sítios arqueológicos mais importantes da Irlanda, habitado há 5.000 anos. O centro de visitantes e o Grange Stone Circle, com 113 pedras, revelam a pré-história do sudoeste.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Curraghchase Forest Park', 'slug' => 'curraghchase-forest-park', 'county' => 'Limerick', 'town' => 'Adare', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Parque florestal com ruínas da mansão De Vere, trilhas, lago e colônia de morcegos protegida.', 'content' => '<p>Curraghchase foi a propriedade do poeta Aubrey de Vere. As ruínas da mansão incendiada em 1941, trilhas sombreadas e o lago com plataforma de observação fazem do parque um refúgio tranquilo.</p>', 'outdoor' => true, 'free' => true ),

	// ---- KILDARE (+8) ----
	array( 'title' => 'Irish National Stud & Japanese Gardens', 'slug' => 'irish-national-stud-japanese-gardens', 'county' => 'Kildare', 'town' => 'Kildare Town', 'category' => 'Vida Selvagem', 'official_website' => 'https://irishnationalstud.ie/', 'discover_ireland' => '', 'excerpt' => 'Haras nacional com garanhões campeões, museu do cavalo e os famosos Jardins Japoneses de 1906.', 'content' => '<p>O Irish National Stud cria garanhões de elite desde 1946. A visita inclui os estábulos, o Horse Museum e os Japanese Gardens — considerados os mais finos da Europa — com o St Fiachra\'s Garden ao lado.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Castletown House', 'slug' => 'castletown-house', 'county' => 'Kildare', 'town' => 'Celbridge', 'category' => 'História', 'official_website' => 'https://heritageireland.ie/places-to-visit/castletown-house-and-parklands/', 'discover_ireland' => 'https://www.discoverireland.ie/kildare/castletown-house', 'excerpt' => 'Mansão palladiana de 1722, a maior da Irlanda, com salões restaurados e parque aberto ao público.', 'content' => '<p>Castletown House foi construída para William Conolly, o homem mais rico da Irlanda do século XVIII. Os interiores incluem a Long Gallery de 24 metros; o parque tem trilhas e o Conolly Folly ao lado.</p>', 'indoor' => true, 'outdoor' => true ),
	array( 'title' => 'Bog of Allen Nature Centre', 'slug' => 'bog-of-allen-nature-centre', 'county' => 'Kildare', 'town' => 'Lullymore', 'category' => 'Vida Selvagem', 'official_website' => 'https://www.ipcc.ie/', 'discover_ireland' => 'https://www.discoverireland.ie/kildare/bog-of-allen-nature-centre', 'excerpt' => 'Centro do Irish Peatland Conservation Council com jardim de sapos, turfeira visitável e exposições sobre pântanos.', 'content' => '<p>O Bog of Allen Nature Centre ensina sobre ecossistemas de turfeira — paisagens que cobrem boa parte do midlands. Visitantes exploram a Girley Bog com guias e conhecem o jardim de anfíbios.</p>', 'indoor' => true, 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Pollardstown Fen', 'slug' => 'pollardstown-fen', 'county' => 'Kildare', 'town' => 'Newbridge', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/kildare/pollardstown-fen', 'excerpt' => 'Maior fen (pântano alcalino) da Irlanda, reserva natural com passarelas e plantas raras de origem glacial.', 'content' => '<p>Pollardstown Fen sobreviveu à última era glacial e abriga plantas e insetos raros. Passarelas de madeira permitem explorar a reserva gratuitamente, perto do Grand Canal.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Maynooth Castle', 'slug' => 'maynooth-castle', 'county' => 'Kildare', 'town' => 'Maynooth', 'category' => 'Castelos', 'official_website' => 'https://heritageireland.ie/places-to-visit/maynooth-castle/', 'discover_ireland' => 'https://www.discoverireland.ie/kildare/maynooth-castle', 'excerpt' => 'Fortaleza dos Fitzgerald, os poderosos condes de Kildare, no campus da universidade mais antiga da Irlanda.', 'content' => '<p>Maynooth Castle foi o centro do poder dos Geraldines até 1535. As ruínas restauradas incluem a torre de menagem com exposição sobre a família FitzGerald. Entrada gratuita.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Donadea Forest Park', 'slug' => 'donadea-forest-park', 'county' => 'Kildare', 'town' => 'Donadea', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/kildare/donadea-forest-park', 'excerpt' => 'Floresta com trilhas, lago, torre do castelo de Aylmer e o 9/11 Memorial Garden.', 'content' => '<p>Donadea Forest Park preserva as ruínas do castelo dos Aylmer e oferece trilhas populares, incluindo a rota de 5 km. O memorial 9/11 homenageia o bombeiro irlandês-americano Sean Tallon.</p>', 'outdoor' => true, 'family' => true, 'free' => true ),
	array( 'title' => 'Lullymore Heritage & Discovery Park', 'slug' => 'lullymore-heritage-park', 'county' => 'Kildare', 'town' => 'Rathangan', 'category' => 'Aventura', 'official_website' => 'https://lullymoreheritagepark.com/', 'discover_ireland' => '', 'excerpt' => 'Parque de descoberta numa ilha de calcário na turfeira, com tren, playground, minigolfe e história da turfa.', 'content' => '<p>Lullymore combina história (mosteiro do século VI, rebelião de 1798) com diversão familiar: mini-trem, playground de madeira, minigolfe e trilhas pela turfeira.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Mondello Park', 'slug' => 'mondello-park', 'county' => 'Kildare', 'town' => 'Naas', 'category' => 'Aventura', 'official_website' => 'https://www.mondellopark.com/', 'discover_ireland' => '', 'excerpt' => 'Único autódromo internacional da Irlanda, com corridas abertas ao público e experiências de pilotagem.', 'content' => '<p>Mondello Park recebe campeonatos nacionais e internacionais de automobilismo e motociclismo. Visitantes assistem às corridas e podem experimentar karting e track days.</p>', 'outdoor' => true, 'family' => true ),

	// ---- LOUTH (+7) ----
	array( 'title' => 'Carlingford', 'slug' => 'carlingford', 'county' => 'Louth', 'town' => 'Carlingford', 'category' => 'Cidades', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Vila medieval preservada na costa do Carlingford Lough, com muralhas, castelo e o Carlingford Oyster Festival.', 'content' => '<p>Carlingford conserva portais medievais, o Tholsel e o King John\'s Castle em ruínas. A vila é famosa pelas ostras, pelas trilhas do Cooley Peninsula e pela vista para as Mourne Mountains.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => "King John's Castle (Carlingford)", 'slug' => 'king-johns-castle-carlingford', 'county' => 'Louth', 'town' => 'Carlingford', 'category' => 'Castelos', 'official_website' => 'https://heritageireland.ie/places-to-visit/carlingford-castle/', 'discover_ireland' => '', 'excerpt' => 'Fortaleza normanda do século XII sobre o Carlingford Lough, com salão medieval e vista para as Mourne Mountains.', 'content' => '<p>Erguido por Hugh de Lacy por volta de 1190, o castelo de Carlingford guardava o porto. O salão do século XIII e as muralhas estão abertos a visitas com vista espetacular do lough.</p>', 'outdoor' => true ),
	array( 'title' => 'Proleek Dolmen', 'slug' => 'proleek-dolmen', 'county' => 'Louth', 'town' => 'Ballymascanlon', 'category' => 'História', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/louth/proleek-dolmen', 'excerpt' => 'Dólmen megalítico com laje de 40 toneladas, cercado de lendas — quem acertar uma pedra no topo terá sorte.', 'content' => '<p>O Proleek Dolmen, no terreno do Ballymascanlon House Hotel, é um dos megálitos mais fotogênicos da Irlanda. A tradição diz que acertar uma pedrinha no topo garante casamento ou boa sorte.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Monasterboice', 'slug' => 'monasterboice', 'county' => 'Louth', 'town' => 'Monasterboice', 'category' => 'História', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Sítio monástico com as alta cruzes mais famosas da Irlanda, incluindo a Muiredach\'s Cross do século X.', 'content' => '<p>Fundado por São Buite no século VI, Monasterboice abriga a Muiredach\'s High Cross, considerada a mais bela da Irlanda, com painéis esculpidos do Antigo e Novo Testamento, além de duas torres redondas.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Mellifont Abbey', 'slug' => 'mellifont-abbey', 'county' => 'Louth', 'town' => 'Collon', 'category' => 'História', 'official_website' => 'https://heritageireland.ie/places-to-visit/old-mellifont-cistercian-abbey-monastic-site/', 'discover_ireland' => '', 'excerpt' => 'Primeira abadia cisterciense da Irlanda (1142), com lavabo octogonal único e ruínas evocativas.', 'content' => '<p>Mellifont ("fonte de mel") introduziu a arquitetura cisterciense na Irlanda e sediou o Sínodo de 1152. O lavabo octogonal restaurado é uma peça arquitetônica rara na Europa.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Carlingford Lough Greenway', 'slug' => 'carlingford-lough-greenway', 'county' => 'Louth', 'town' => 'Carlingford – Newry', 'category' => 'Greenways', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Greenway de 10 km ao longo do lough, entre Carlingford e Newry, com vista para as Mourne Mountains.', 'content' => '<p>O Carlingford Lough Greenway segue a antiga linha férrea por 10 km planos entre a vila medieval e a fronteira. Ideal para bicicleta com crianças, com paradas em Omeath e Victoria Lock.</p>', 'outdoor' => true, 'family' => true, 'free' => true ),
	array( 'title' => 'Millmount Fort & Museum', 'slug' => 'millmount-fort-museum', 'county' => 'Louth', 'town' => 'Drogheda', 'category' => 'Museus', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Fortaleza sobre motte normanda com vista de Drogheda, abrigando o museu municipal e a torre Martello.', 'content' => '<p>Millmount domina Drogheda desde o século XII. O complexo inclui o County Museum, com exposições sobre a Batalha do Boyne e a história local, e a torre Martello do século XIX.</p>', 'indoor' => true, 'outdoor' => true ),

	// ---- CARLOW (+7) ----
	array( 'title' => 'Brownshill Dolmen', 'slug' => 'brownshill-dolmen', 'county' => 'Carlow', 'town' => 'Carlow', 'category' => 'História', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/carlow/brownshill-dolmen', 'excerpt' => 'Dólmen com a maior laje de cobertura da Europa: 100 toneladas de granito sobre pedras de suporte de 5.000 anos.', 'content' => '<p>O Brownshill Dolmen impressiona pela escala: sua laje de granito pesa cerca de 100 toneladas e é a maior da Europa. O monumento neolítico fica a poucos minutos do centro de Carlow.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Altamont Gardens', 'slug' => 'altamont-gardens', 'county' => 'Carlow', 'town' => 'Tullow', 'category' => 'Jardins', 'official_website' => 'https://heritageireland.ie/places-to-visit/altamont-gardens/', 'discover_ireland' => 'https://www.discoverireland.ie/carlow/altamont-gardens', 'excerpt' => 'Jardins românticos do século XVIII com lago, arboreto e o "corredor de azaleias" — entrada gratuita.', 'content' => '<p>Altamont é chamado de "o jardim mais romântico da Irlanda". O lago espelhado, as árvores antigas e a coleção de bulbos e azaleias fazem dele um destino de todas as estações. Gerido pelo OPW, é gratuito.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => "Duckett's Grove", 'slug' => 'ducketts-grove', 'county' => 'Carlow', 'town' => 'Keenogue', 'category' => 'Castelos', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Ruínas góticas vitorianas da mansão Duckett, com walled gardens restaurados e parque público.', 'content' => '<p>Duckett\'s Grove foi uma grande mansão gótica até o incêndio de 1933. As torres em ruínas e os jardins murados restaurados, com roseiras históricas, são hoje um parque público gratuito.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Huntington Castle & Gardens', 'slug' => 'huntington-castle-gardens', 'county' => 'Carlow', 'town' => 'Clonegal', 'category' => 'Castelos', 'official_website' => 'https://huntingtoncastle.com/', 'discover_ireland' => '', 'excerpt' => 'Castelo de 1625 da família Durdin-Robertson, com porões medievais, jardins murados e templo druídico.', 'content' => '<p>Huntington Castle, em Clonegal, oferece tours guiados pelos porões do século XVII, salões históricos e jardins murados com o famoso yew walk. A vila de Clonegal venceu prêmios de vila mais bonita da Irlanda.</p>', 'indoor' => true, 'outdoor' => true ),
	array( 'title' => 'Borris House', 'slug' => 'borris-house', 'county' => 'Carlow', 'town' => 'Borris', 'category' => 'História', 'official_website' => 'https://borrishouse.com/', 'discover_ireland' => 'https://www.discoverireland.ie/carlow/borris-house', 'excerpt' => 'Casa ancestral dos MacMurrough Kavanagh, reis de Leinster, com salões Tudor e mercado de artesãos.', 'content' => '<p>Borris House guarda 800 anos de história ligada aos reis gaélicos de Leinster. Aberta na temporada com tours guiados, inclui a fábrica de renda Borris Lace e eventos de artesanato.</p>', 'indoor' => true, 'outdoor' => true ),
	array( 'title' => 'Oak Park Forest Park', 'slug' => 'oak-park-forest-park', 'county' => 'Carlow', 'town' => 'Carlow', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/carlow/oak-park-forest-park', 'excerpt' => 'Floresta de carvalhos e faías com trilhas, lagos e o Oak Park Lake, perto da cidade de Carlow.', 'content' => '<p>Oak Park Forest Park oferece caminhadas tranquilas entre árvores centenárias, com dois lagos e observação de aves aquáticas. Um dos espaços verdes favoritos dos moradores de Carlow.</p>', 'outdoor' => true, 'family' => true, 'free' => true ),
	array( 'title' => 'Mount Leinster & Nine Stones', 'slug' => 'mount-leinster-nine-stones', 'county' => 'Carlow', 'town' => 'Borris', 'category' => 'Caminhadas', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Ponto mais alto das Blackstairs Mountains (795 m), com mirante dos Nine Stones e vista para quatro condados.', 'content' => '<p>Mount Leinster domina o sul de Carlow. A estrada até os Nine Stones e a trilha até o topo recompensam com vistas de Wexford, Kilkenny, Carlow e Wicklow — e é um clássico do parapente irlandês.</p>', 'outdoor' => true, 'free' => true ),
);